  loading: boolean;
  onSubmit: (data: FormForgotPassword) => void;
}

export function ForgotPasswordForm({ loading, onSubmit }: ForgotPasswordFormProps): ReactElement {
  const intl = useIntl();
  const { emailSchema } = useFormValidation();

  const schema = z.object({
    email: emailSchema,
  });

  const form = useForm({
    defaultValues: {
      email: "",
    },
    validators: {
      onSubmit: schema,
    },
