              >
                {isVisible ? <EyeIcon className="h-5 w-5" /> : <EyeSlashIcon className="h-5 w-5" />}
              </button>
            }
            data-testid="login-form__password-input"
          />
        )}
      />
      <div className="flex w-full items-center justify-between gap-3">
        <form.Field
